from collections import Counter

SENTINEL_MAX_LEN = 1 << 30


class Solution:
    def minWindow(self, s: str, t: str) -> str:
        m = len(s)
        n = len(t)
        if m < n:
            return ""

        remaining_chars = Counter(t)  # SC=O(1), TC=O(n)
        start, end, min_start, min_len = 0, 0, 0, SENTINEL_MAX_LEN
        counter = n  # how many characters of t aren't present in s[start: end].
        # when counter becomes zero, then s[start: end] is a candidate.
        size = m
        # We'll be progressively checking relevant substrings s[start: end] for various combinations of (start, end).
        # We'll start with start = 0, and increase the value of end till the substring s[start: end] has
        # all the characters of string t in it (checked by when counter goes down to 0).
        # Optimization: initially we skip all those characters which aren't in t as they are pointless for our search.
        while start < size and (
            s[start] not in remaining_chars or remaining_chars[s[start]] == 0
        ):
            start += 1
        end = start
        while end < size:  # SC=O(1), TC=O(size)
            end_char = s[end]
            # If s[end] is missing in s[start: end-1], then decrease counter to indicate that
            # s[end] helps decrease the counter.
            if remaining_chars[end_char] > 0:
                counter -= 1
            # Decrease remaining_chars[end_char].
            # If end_char does not exist in t, then remaining_char_counters[end_char] will be negative.
            remaining_chars[end_char] -= 1
            end += 1  # ensures that the current substring under check is s[start: end]
            # Now, we'll try to increase start to find its highest value, to see if s[start: end]
            # still contains all characters of t in it and end-start is shorter than
            # the last known shortest substring. Basically, slide the left end of the window right by 1
            # to see if it's still a valid candidate.
            while counter == 0:  # SC=O(1), TC=O(size)
                start_char = s[start]
                # Optimization: skip those chars from start onwards which are extra in s[start:end].
                if start_char in remaining_chars and remaining_chars[start_char] < 0:
                    remaining_chars[start_char] += 1
                    start += 1
                    continue
                if end - start < min_len:
                    min_len = end - start
                    min_start = start
                    # Optimization:
                    if end - start == n:
                        # can't be shorter than this, so there is no point looking further.
                        return s[start:end]
                remaining_chars[start_char] += 1  # Now, we try to move start 1 forward.
                if remaining_chars[start_char] > 0:
                    counter += 1
                start += 1
                # at the end when we hit a start where s[start: end] doesn't qualify then we try to increment
                # end to find another shorter end-start range which qualifies.

        # if we ever found any qualifying substring, then min_len will not be equal to SENTINEL_MAX_LEN.
        return s[min_start : min_start + min_len] if min_len != SENTINEL_MAX_LEN else ""


import sys

from utils.context_manager import TimeoutException, time_limit
from utils.pretty_test_runner import pretty_test_runner, truncate_param


@pretty_test_runner(time_limit_in_sec=0.05, stop_on_tc_failure=False)
def Test(s: str, t: str, expected: str) -> tuple[bool, str]:
    actual = Solution().minWindow(s, t)
    if actual != expected:
        return (
            False,
            f"got='{truncate_param(actual)}', wanted='{truncate_param(expected)}', for s='{truncate_param(s)}', t='{truncate_param(t)}'",
        )
    return True, ""


def main():
    try:
        with time_limit(5):  # 5-second time limit
            Test(s="ADOBECODEBANC", t="ABC", expected="BANC")
            Test(s="a", t="a", expected="a")
            Test(s="a", t="aa", expected="")
            Test(s="abc", t="d", expected="")
            Test(
                s="".join(["a"] * (10**5)),
                t="".join(["a"] * (5 * 10**4)),
                expected="".join(["a"] * (5 * 10**4)),
            )
            Test(
                s="",
                t="",
                expected="",
            )
            Test(s="acbac", t="ab", expected="ba")
            Test(s="acccccbac", t="ab", expected="ba")
            Test(s="acccccbcab", t="ab", expected="ab")
    except TimeoutException:
        print("The tests took too long and were terminated!")
        sys.exit(1)


if __name__ == "__main__":
    main()
